#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum CompilationUnitItem<'a> {
    PackageDeclaration(PackageDeclaration<'a>),
    ImportDeclaration(ImportDeclaration<'a>),
    ModuleDeclaration(ModuleDeclaration<'a>),
    ClassDeclaration(ClassDeclaration<'a>),
    RecordDeclaration(RecordDeclaration<'a>),
    EnumDeclaration(EnumDeclaration<'a>),
    InterfaceDeclaration(InterfaceDeclaration<'a>),
    AnnotationInterfaceDeclaration(AnnotationInterfaceDeclaration<'a>),
    FieldDeclaration(FieldDeclaration<'a>),
    MethodDeclaration(MethodDeclaration<'a>),
    EmptyDeclaration(EmptyDeclaration<'a>),
    Bogus(Bogus<'a>),
}

impl<'a> AstNode<'a> for CompilationUnitItem<'a> {
    fn can_cast(kind: RawSyntaxKind) -> bool {
        matches!(
            K::from_raw(kind),
            K::PackageDeclaration
                | K::ImportDeclaration
                | K::ModuleDeclaration
                | K::ClassDeclaration
                | K::RecordDeclaration
                | K::EnumDeclaration
                | K::InterfaceDeclaration
                | K::AnnotationInterfaceDeclaration
                | K::FieldDeclaration
                | K::MethodDeclaration
                | K::EmptyDeclaration
                | K::Bogus
        )
    }
    fn cast(node: SyntaxNode<'a>) -> Option<Self> {
        Some(match K::from_raw(node.kind()) {
            K::PackageDeclaration => Self::PackageDeclaration(PackageDeclaration(node)),
            K::ImportDeclaration => Self::ImportDeclaration(ImportDeclaration(node)),
            K::ModuleDeclaration => Self::ModuleDeclaration(ModuleDeclaration(node)),
            K::ClassDeclaration => Self::ClassDeclaration(ClassDeclaration(node)),
            K::RecordDeclaration => Self::RecordDeclaration(RecordDeclaration(node)),
            K::EnumDeclaration => Self::EnumDeclaration(EnumDeclaration(node)),
            K::InterfaceDeclaration => Self::InterfaceDeclaration(InterfaceDeclaration(node)),
            K::AnnotationInterfaceDeclaration => {
                Self::AnnotationInterfaceDeclaration(AnnotationInterfaceDeclaration(node))
            }
            K::FieldDeclaration => Self::FieldDeclaration(FieldDeclaration(node)),
            K::MethodDeclaration => Self::MethodDeclaration(MethodDeclaration(node)),
            K::EmptyDeclaration => Self::EmptyDeclaration(EmptyDeclaration(node)),
            K::Bogus => Self::Bogus(Bogus(node)),
            _ => return None,
        })
    }
    fn syntax(self) -> SyntaxNode<'a> {
        match self {
            Self::PackageDeclaration(node) => node.syntax(),
            Self::ImportDeclaration(node) => node.syntax(),
            Self::ModuleDeclaration(node) => node.syntax(),
            Self::ClassDeclaration(node) => node.syntax(),
            Self::RecordDeclaration(node) => node.syntax(),
            Self::EnumDeclaration(node) => node.syntax(),
            Self::InterfaceDeclaration(node) => node.syntax(),
            Self::AnnotationInterfaceDeclaration(node) => node.syntax(),
            Self::FieldDeclaration(node) => node.syntax(),
            Self::MethodDeclaration(node) => node.syntax(),
            Self::EmptyDeclaration(node) => node.syntax(),
            Self::Bogus(node) => node.syntax(),
        }
    }
}

impl<'a> CompilationUnitItem<'a> {
    pub fn cast_element(element: SyntaxElement<'a>) -> Option<Self> {
        element.as_node().and_then(Self::cast)
    }
}

fn is_compilation_unit_item(kind: JavaSyntaxKind) -> bool {
    matches!(
        kind,
        K::PackageDeclaration
            | K::ImportDeclaration
            | K::ModuleDeclaration
            | K::ClassDeclaration
            | K::RecordDeclaration
            | K::EnumDeclaration
            | K::InterfaceDeclaration
            | K::AnnotationInterfaceDeclaration
            | K::FieldDeclaration
            | K::MethodDeclaration
            | K::EmptyDeclaration
            | K::Bogus
    )
}

